B.W8=new A.Z(B.v,["J\xe1 t\xf4 aqui, ZEK! Para de tremer esse rabo!","I'm here, ZEK! Stop shaking that tail!","\xa1Ya estoy aqu\xed, ZEK! \xa1Deja de temblar esa cola!"],t.w)
